#!/usr/bin/env python3
"""Self-contained human-readable HTML for the frozen execution audit artifacts."""
import argparse
import io
import json
from pathlib import Path
import subprocess


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--evidence", required=True)
    p.add_argument("--out", required=True)
    a = p.parse_args()
    root = Path(a.evidence)
    keys = ["baseline", "fixed", "expanded", "expanded-axis", "strategies", "strategies-axis-block", "isolated-ranges", "isolated-axis-ranges", "window-calibration", "market-200"]
    data = {k: json.loads((root / (k + ".json")).read_text()) for k in keys}
    data["market"] = json.loads((root / "market-12/_meta.json").read_text())
    data["commit"] = subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip()
    data["preset"] = json.loads((root / "expanded-patch.json").read_text())
    data["tests"] = (root / "regression-final.log").read_text().splitlines()[-1]
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    fig, axes = plt.subplots(2, 1, figsize=(12, 6), layout="constrained")
    for key, label, color in (("baseline", "Original", "#7c8699"), ("fixed", "Entry fixes · Axis off", "#c07816"), ("expanded-axis", "A-O additions · current Axis", "#14766c")):
        d = data[key]; equity = 0; xs = [0]; ys = [0]
        start = data["expanded-axis"]["start_utc"]
        for r in sorted(d["trades"], key=lambda r: r["t_out"]):
            equity += r["net_pct"]; xs.append((r["t_out"] - start) / 3600); ys.append(equity)
        axes[0].step(xs, ys, where="post", label=label, color=color, linewidth=1.8)
    axes[0].set(ylabel="Cumulative net / base notional (%)", xlim=(0,24), title="Closed-trade paths • equal base notional, no compounding")
    axes[0].legend(fontsize=9); axes[0].grid(alpha=.2); axes[0].axhline(0, color="#999", linewidth=.7)
    h = data["expanded-axis"]["hourly"]
    axes[1].bar(range(24), [x["net_pct"] for x in h], color=["#14766c" if x["net_pct"] >= 0 else "#b34735" for x in h])
    axes[1].set(xlabel="Hours since 2026-11-06 19:00 UTC", ylabel="Net / base notional (%)", title="Hourly entry cohorts • final outcome of positions opened in that hour", xticks=list(range(0,24,2)))
    axes[1].grid(axis="y", alpha=.2)
    buf=io.StringIO(); fig.savefig(buf, format="svg"); plt.close(fig)
    plot=buf.getvalue()[buf.getvalue().index("<svg"):]
    template = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CTS-G · 24-hour execution audit</title><style>
:root{--ink:#132c37;--muted:#5c6f78;--line:#dce5e9;--accent:#14766c;--bad:#a43c2c}*{box-sizing:border-box}body{margin:0;background:#f4f7f8;color:var(--ink);font:15px/1.55 system-ui,sans-serif}header{background:#132c37;color:white;padding:42px max(24px,calc((100vw - 1250px)/2))}header small{letter-spacing:.14em;text-transform:uppercase;color:#a9d5ce}h1{font-size:clamp(28px,4vw,46px);letter-spacing:-.035em;margin:10px 0}h2{font-size:24px;letter-spacing:-.02em;margin:0 0 14px}h3{font-size:18px}p{max-width:100ch}main{max-width:1300px;margin:auto;padding:24px}section{background:white;border:1px solid var(--line);border-radius:12px;padding:24px;margin:0 0 20px}nav{display:flex;gap:18px;flex-wrap:wrap;margin-top:20px}a{color:var(--accent)}header a{color:#b8e7e0}.muted{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{padding:18px;border:1px solid var(--line);border-top:3px solid var(--accent);border-radius:8px}.number{font-size:32px;font-weight:750;letter-spacing:-.04em}.notice{background:#fff6e5;border-left:4px solid #bd7a12;padding:16px 20px;margin:20px 0}.controls{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:16px 0}label{font-size:13px;display:grid;gap:5px}select,input,button{font:inherit;padding:9px 12px;border:1px solid #b8cbd2;border-radius:6px;background:white;color:var(--ink)}input{min-width:240px}button{cursor:pointer}.scroll{overflow:auto;max-height:620px;border:1px solid var(--line);border-radius:7px}table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th{position:sticky;top:0;background:#edf3f5;text-align:left;color:#38515d}td,th{padding:10px 12px;border-bottom:1px solid var(--line)}tbody tr:hover{background:#f0f8f6}.negative{color:var(--bad)}.positive{color:var(--accent)}svg{width:100%;height:auto}summary{cursor:pointer;font-weight:650;padding:8px 0}code{font-size:12px;overflow-wrap:anywhere}footer{padding:16px;color:var(--muted)}@media(max-width:700px){main{padding:10px}section{padding:16px}.cards{grid-template-columns:1fr 1fr}.number{font-size:27px}.controls>*{width:100%}input{min-width:0;width:100%}}
</style><header><small>CTS-G / Stable-02-01 / Reproducible execution review</small><h1>From validation to executed trades</h1><div>12 symbols · 24 hours · 6–7 November 2026 · UTC</div><nav><a href="#comparison">Comparison</a><a href="#hourly">Hourly</a><a href="#groups">Indications & ranges</a><a href="#stages">Stages</a><a href="#strategies">Axis & Block</a><a href="#trades">Trades</a><a href="#methods">Method</a></nav></header><main>
<section><h2>Execution is the acceptance measure</h2><div class="cards" id="cards"></div><div class="notice"><b>Profitability is not uniform.</b> Micro and some Exit/Trailing portfolios lose money in these tests. The additions remain an opt-in research preset. The results do not establish that future PF will stay high. Open positions and weak variants are retained in this report.</div><p class="muted">Main result: imported CTS-A-O coordinations with the existing four Axis rules. Cost is 0.11% per completed position: two public taker fees of 0.05%, plus slippage equal to 10% of those fees. Funding, account-specific commissions, order-book liquidity and exchange fills are not modeled.</p>__PLOT__</section>
<section id="comparison"><h2>Same market snapshot, explicit controls</h2><div id="comparison-table"></div><p class="muted">Net and drawdown are percentages of one equal base position’s notional; they are not account returns. Original Base-validation statistics used a different population and are omitted from this comparison. Marked PF adds estimated exit costs for open positions.</p></section>
<section id="hourly"><h2>Detailed hourly outcomes</h2><p>Closed-trade outcomes grouped by entry hour. Stage validation is sampled at the beginning of each hour; execution rechecks eligibility at each signal.</p><label>Portfolio<select id="portfolio"></select></label><div id="hour-table"></div></section>
<section id="groups"><h2>Indications, types, distances and directions</h2><div class="controls"><label>Breakdown<select id="group-kind"><option value="types">Indication × type</option><option value="tpranges">Indication × type × range</option><option value="tpranges_all">Type × range</option><option value="ranges">Every TP step / trailing pair</option><option value="sl">Every SL ratio</option><option value="sides">Direction</option></select></label><label>Filter<input id="group-filter" placeholder="micro, minimal, short, ao_lr, trail…"></label></div><div id="group-table"></div><p class="muted">Base PF and next-N PF pool windows across sampled decisions, so overlapping evidence is counted more than once. They are selection diagnostics, not portfolio PF. A next-N trade must enter after the validation decision.</p></section>
<section id="stages"><h2>Independent last-N stage windows</h2><div class="controls"><label>Dimension<select id="dimension"><option>all</option><option>type</option><option>tprange</option><option>side</option></select></label><label>Stage<select id="stage"></select></label><label>Group filter<input id="stage-filter" placeholder="Indication / type / range"></label></div><div id="stage-table"></div><p class="muted">Each row shows the number evaluated, passing count, pass rate, and pooled PF of passing windows only. Different stages use different historical populations; their PF need not be monotonic. Passing windows are not a forecast of future returns.</p></section>
<section id="strategies"><h2>Axis and Block, including unsuccessful variants</h2><div id="strategy-table"></div><p class="muted">Block sizes are volume weighted per filled count, including carry scale. Additive and Shared relation tests use the same parents within each control. Closed positions only in this comparison; the complete main-portfolio mark is above. “Current” Block produced no adds in this window.</p><details><summary>Hourly Axis / Block results</summary><label>Variant<select id="strategy-choice"></select></label><div id="strategy-hourly"></div></details></section>
<section><h2>Range and type isolation</h2><p>Each row is a separate portfolio with the current Axis rules. These counts cannot be added to the combined portfolio. A zero-set Micro Trailing row means the configured trailing-distance floor is incompatible with a Micro arm.</p><div id="isolated-table"></div><details><summary>Last-N calibration from earlier data</summary><p>Four predeclared window choices were compared on the previous 12 hours. Selection uses only that earlier period; the next 24 hours are reported separately. This is exploratory research after inspecting the general replay, not an untouched holdout. It does not change live defaults.</p><div id="calibration-table"></div></details></section>
<section id="trades"><h2>Executed positions and final open marks</h2><div class="controls"><label>Trade filter<input id="trade-filter" placeholder="Symbol, indication, lane or reason"></label></div><div id="trade-table"></div><h3>Open at the final timestamp</h3><div id="open-table"></div></section>
<section><h2>200-symbol public-data readiness</h2><p id="readiness"></p><details><summary>Every symbol</summary><div id="market-table"></div></details></section>
<section id="methods"><h2>Evidence and limits</h2><ul><li>Snapshot: 49 complete hours of contiguous 1-minute BingX OHLCV per symbol. Main replay: 24 hours of history, then 24 report hours, plus alignment coverage.</li><li>One open parent position per symbol. Each paper Set, direction and lane has independent evaluation; execution ranks eligible candidates. Multiple filled add orders can belong to the same parent.</li><li>No strategy profit guarantee, loss removal, PF floor-clamping, or selection from future trades. PF 99 in source files denotes positive results with no observed loss; tables display it as “no losses.”</li><li>The CTS-A-O port covers 5 methods × 13 relations × 10 windows × 3 timeframes = 1,950 signal names. A 15-name preset is replayed here. Reference vectors check 390,000 raw direction decisions; CTS-G retains its causal timeframe aggregation and execution rules.</li><li>All 12 fixed symbols were chosen before forward returns. Results include both long and short trades, selected lanes, reasons, and final open-position marks.</li><li>No x01 authentication, private balance check, live order, or exchange fill confirmation was performed. The 200-symbol result is market/indication readiness only.</li><li>All new Python trading logic is exercised by regression checks. The imported preset is opt-in; existing account settings were not replaced.</li></ul><p id="test-result"></p><p>Code checkout: <code id="commit"></code></p><details><summary>Symbols and imported coordinations</summary><p id="symbols"></p><div id="preset-table"></div></details></section>
<footer>Generated from saved market data, engine fingerprints and replay results. All timestamps are UTC. Review losing variants and marked exposure before interpreting a closed-trade PF.</footer></main>
<script id="audit-data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('audit-data').textContent),$=id=>document.getElementById(id);const names={'baseline':'Original Stable-02-01 · Axis off','fixed':'Entry fixes · Axis off','expanded':'A-O additions · Axis off','expanded-axis':'A-O additions · current Axis'};
const fmt=x=>x==null?'—':typeof x==='number'?(Number.isInteger(x)?String(x):x.toFixed(3)):String(x);const date=t=>new Date(t*1000).toISOString().replace('T',' ').slice(0,16);const PF=x=>x===99?'no losses':fmt(x);
function table(id,rows,cols){const box=$(id);box.replaceChildren();const wrap=document.createElement('div');wrap.className='scroll';const t=document.createElement('table'),head=t.createTHead().insertRow();for(const [k,l] of cols){const h=document.createElement('th');h.textContent=l;head.append(h)}const body=t.createTBody();for(const r of rows){const tr=body.insertRow();for(const [k,l,f] of cols){const td=tr.insertCell();td.textContent=f?f(r[k]):fmt(r[k]);if(typeof r[k]==='number'&&k.includes('net'))td.className=r[k]<0?'negative':'positive'}}wrap.append(t);box.append(wrap);const count=document.createElement('p');count.className='muted';count.textContent=rows.length+' rows';box.append(count)}
function option(el,v,label=v){const o=document.createElement('option');o.value=v;o.textContent=label;el.append(o)}for(const k of Object.keys(names))option($('portfolio'),k,names[k]);$('portfolio').value='expanded-axis';
const current=D['expanded-axis'];const cards=[['Executed PF',PF(current.all.exec_pf)],['Closed + marked PF',PF(current.closed_and_marked_pf)],['Closed positions',current.all.orders],['Open at end',current.open_at_end.length]];for(const [label,n]of cards){const e=document.createElement('div');e.className='card';const a=document.createElement('div');a.textContent=label;const b=document.createElement('div');b.className='number';b.textContent=n;e.append(a,b);$('cards').append(e)}
const comp=Object.keys(names).map(k=>({name:names[k],...D[k].all,marked:D[k].closed_and_marked_pf,open:D[k].open_at_end.length}));table('comparison-table',comp,[['name','Portfolio'],['orders','Closed'],['exec_pf','Executed PF',PF],['marked','Closed + marked PF',PF],['net_pct','Net %'],['win_pct','Win %'],['open','Open']]);
const groupCols=[['group','Group'],['sets','Sets'],['valid_pct','Base valid %'],['executable_pct','Main/Real eligible %'],['eff_pf','Base selected PF',PF],['next8_pf','Next 8 PF',PF],['next50_pf','Next 50 PF',PF],['orders','Executed'],['exec_pf','Executed PF',PF],['net_pct','Net %'],['min_n','Fewest Base samples']];
function render(){const d=D[$('portfolio').value];table('hour-table',d.hourly,[['t','Entry hour UTC',date],['valid_pct','Base valid %'],['executable_pct','Eligible %'],['eff_pf','Base selected PF',PF],['orders','Closed positions'],['wins','Wins'],['exec_pf','Executed PF',PF],['net_pct','Net %']]);table('group-table',d[$('group-kind').value].filter(r=>r.group.toLowerCase().includes($('group-filter').value.toLowerCase())),groupCols);const rows=d.stage_evaluations||[];table('stage-table',rows.filter(r=>r.dimension===$('dimension').value&&(!$('stage').value||r.stage===$('stage').value)&&r.group.toLowerCase().includes($('stage-filter').value.toLowerCase())),[['t','UTC',date],['group','Group'],['stage','Window'],['evaluated','Evaluated'],['passed','Passed'],['passed_pct','Pass %'],['selection_pf','Selected PF',PF],['orders','Window observations']]);table('trade-table',d.trades.filter(r=>Object.values(r).join(' ').toLowerCase().includes($('trade-filter').value.toLowerCase())),[['t_in','Entry UTC',date],['t_out','Exit UTC',date],['symbol','Symbol'],['pack','Indication'],['kind','Type'],['tp_range','Range'],['side','Direction',x=>x===1?'Long':x===-1?'Short':'Both'],['lane','Lane'],['reason','Exit'],['net_pct','Net %'],['set','Set ID']]);table('open-table',d.open_at_end,[['symbol','Symbol'],['t_in','Entry UTC',date],['kind','Type'],['side','Side'],['lane','Lane'],['entry','Entry'],['mark','Mark'],['mark_net_pct','Marked net %']])}
option($('stage'),'','All windows');[...new Set(current.stage_evaluations.map(r=>r.stage))].sort().forEach(s=>option($('stage'),s));for(const id of ['portfolio','group-kind','group-filter','dimension','stage','stage-filter','trade-filter'])$(id).addEventListener(id.includes('filter')?'input':'change',render);render();
const strategies=[];for(const [label,s]of Object.entries(D.strategies.axis))strategies.push({label:'Axis · '+label,...s});for(const [file,prefix]of [['strategies','Block · Axis off · '],['strategies-axis-block','Block · current Axis · ']])for(const[label,s]of Object.entries(D[file].block2.results))strategies.push({label:prefix+label,...s});table('strategy-table',strategies,[['label','Variant'],['parents','Parents'],['adds','Adds'],['pf','Weighted PF',PF],['net_pct','Net %'],['max_dd_pct','Closed DD %'],['adds_pf','Adds PF',PF],['adds_net_pct','Adds net %'],['hours_positive','Positive close hours']]);strategies.forEach((s,i)=>option($('strategy-choice'),i,s.label));function strategyHourly(){table('strategy-hourly',strategies[+$('strategy-choice').value].hourly,[['t','Close hour UTC',date],['fills','Fills'],['pf','PF',PF],['net_pct','Net %']])}$('strategy-choice').onchange=strategyHourly;strategyHourly();
table('isolated-table',D['isolated-axis-ranges'].results,[['type','Type'],['range','Range'],['sets','Sets'],['parents','Closed'],['ao_orders','A-O closed'],['pf','Executed PF',PF],['net_pct','Net %'],['max_dd_pct','Closed DD %'],['open_at_end','Open'],['hours_positive','Positive close hours']]);
const cal=D['window-calibration'].chosen.map(r=>({range:r.range,label:r.label,train:r.training.pf,forward:r.forward.pf,marked:r.forward.marked_pf,orders:r.forward.parents,net:r.forward.net_pct}));table('calibration-table',cal,[['range','Range'],['label','Selected windows'],['train','Prior 12h PF',PF],['forward','Next 24h PF',PF],['marked','Next 24h marked PF',PF],['orders','Closed'],['net','Net %']]);
$('readiness').textContent=D['market-200'].passed+' / '+D['market-200'].symbols+' symbols passed complete 720-minute OHLCV checks and 15-indication processing. No authenticated account actions or orders.';table('market-table',D['market-200'].results,[['symbol','Symbol'],['ok','Passed'],['bars','Candles'],['signals','Current signals'],['seconds','Seconds'],['error','Error']]);$('test-result').textContent=D.tests;$('commit').textContent=D.commit;$('symbols').textContent=current.symbols.join(', ');table('preset-table',D.preset.indicationConfigs.flatMap(e=>e.names.map(n=>({name:n,steps:e.stepMin+'–'+e.stepMax,ratios:e.slRatios.join(', '),types:e.types.join(', ')}))),[['name','Coordination'],['steps','TP steps'],['ratios','SL / TP'],['types','Types']]);
</script></html>'''
    content = template.replace("__PLOT__",plot).replace("__DATA__",json.dumps(data,separators=(",",":"),allow_nan=False).replace("<","\\u003c"))
    Path(a.out).write_text(content)
    print(f"{a.out}: {len(content):,} characters")


if __name__ == "__main__":
    main()
